def tile(pid,title,plus,minus):
 p=photos[pid]
 return dict(photo_id=pid,asset=p['asset'],crop=p.get('crop'),title=title,plus=plus,minus=minus)
def model(number,tiles,groups,conclusion,review=None):
 old=next(x for x in previous['models'] if x['number']==number)
 fact=re.sub(r'\s*\[S[^\]]+\]','',' '.join(old['facts']))
 return dict(number=number,title=old['title'],facts=fact,tiles=tiles,groups=groups,conclusion=conclusion,review=review,
  maker_sources=[dict(title=old_refs[s]['title'],url=old_refs[s]['url']) for s in old['sources']])

